const body = $('Webhook').item.json.body || $input.item.json;

const systemPrompt = [
  'Eres el clasificador de intenciones de un lavadero de autos en Colombia.',
  'Recibes un mensaje de WhatsApp de un cliente y devuelves su intencion y las entidades que menciona.',
  '',
  'Intenciones:',
  '- greeting: saludos y aperturas de conversacion sin pedido concreto.',
  '- check_status: pregunta por el estado o avance de su vehiculo, o cuando estara listo.',
  '- list_services: pregunta por servicios, precios, tarifas o que ofrecen.',
  '- customer_history: pregunta por sus visitas o turnos anteriores.',
  '- book_appointment: quiere agendar, reservar o pedir un turno.',
  '- human_help: pide hablar con una persona, asesor u operador.',
  '- unknown: cualquier otra cosa, o si el mensaje es ambiguo.',
  '',
  'Entidades:',
  '- plate: la placa del vehiculo si aparece. En Colombia son 3 letras y 3 numeros',
  '  (ABC123) para carros, o 3 letras y 2 numeros (ABC12) para motos. Devuelvela',
  '  sin guiones ni espacios y en mayusculas. null si no aparece.',
  '- customerName: el nombre del cliente si lo menciona. null si no.',
  '- serviceKeyword: la palabra con la que nombra el servicio que quiere',
  '  (lavado, premium, detailing, aspirado...). null si no menciona ninguno.',
  '',
  'El cliente escribe informalmente, con errores de tipeo y sin tildes. Interpreta la',
  'intencion real, no la literalidad. Si dudas entre una intencion concreta y unknown,',
  'elige unknown: es mejor mostrar el menu que responder algo equivocado.',
].join('\n');

// Cuerpo completo de la peticion a la API de Claude.
// Se arma aca (y no en el nodo HTTP) para que sea legible y testeable.
const claudeBody = {
  model: 'claude-haiku-4-5',
  // La salida es un JSON chico; sin thinking no hace falta mas margen.
  max_tokens: 512,
  // Ojo al tocar esto: Haiku 4.5 no admite thinking adaptativo ni
  // output_config.effort (devuelve error). Solo va format.
  output_config: {
    // Garantiza que la respuesta sea JSON valido con esta forma exacta.
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          intent: {
            type: 'string',
            enum: [
              'greeting',
              'check_status',
              'list_services',
              'customer_history',
              'book_appointment',
              'human_help',
              'unknown',
            ],
          },
          entities: {
            type: 'object',
            properties: {
              plate: { anyOf: [{ type: 'string' }, { type: 'null' }] },
              customerName: { anyOf: [{ type: 'string' }, { type: 'null' }] },
              serviceKeyword: { anyOf: [{ type: 'string' }, { type: 'null' }] },
            },
            required: ['plate', 'customerName', 'serviceKeyword'],
            additionalProperties: false,
          },
        },
        required: ['intent', 'entities'],
        additionalProperties: false,
      },
    },
  },
  system: systemPrompt,
  messages: [{ role: 'user', content: String(body.message || '') }],
};

return {
  claudeBody,
  tenantPhone: body.tenantPhone,
  clientPhone: body.phone || null,
  // WhatsApp no entrega el telefono: el LID es el identificador real.
  clientLid: body.waLid || null,
  pushName: body.pushName || null,
  messageId: body.messageId,
  originalMessage: body.message,
};

const resp = $input.item.json;
const prev = $('Preparar Solicitud Claude').item.json;

const VALID_INTENTS = [
  'greeting', 'check_status', 'list_services',
  'customer_history', 'book_appointment', 'human_help', 'unknown',
];

/**
 * Clasificacion por palabras clave.
 *
 * Se usa cuando Claude no esta disponible: sin credito, caido, con la key
 * vencida. Entiende bastante menos que el modelo, pero mantiene el bot util
 * en vez de contestarle "no entendi" a todo el mundo hasta que alguien note
 * que la API dejo de responder.
 */
function clasificarPorPalabras(texto) {
  const raw = String(texto || '');
  const m = raw.toLowerCase();
  const entities = { plate: null, customerName: null, serviceKeyword: null };

  const placa = raw.match(/\b([A-Z]{3}[-\s]?\d{2,3})\b/i);
  if (placa) entities.plate = placa[1].replace(/[-\s]/g, '').toUpperCase();

  let intent = 'unknown';
  if (/\b(hola|buen[oa]s|buenos\s+d[ií]as|saludos|hey|qu[eé]\s+tal)\b/.test(m)) {
    intent = 'greeting';
  } else if (/\b(estado|c[oó]mo\s+va|cu[aá]ndo|listo|mi\s+carro|mi\s+moto|mi\s+veh[ií]culo|mi\s+turno)\b/.test(m)) {
    intent = 'check_status';
  } else if (/\b(servicio|precio|cu[aá]nto|tarifa|cat[aá]logo|ofrecen|valor|cuesta)\b/.test(m)) {
    intent = 'list_services';
  } else if (/\b(historial|mis\s+visitas|visitas\s+anteriores|mis\s+turnos)\b/.test(m)) {
    intent = 'customer_history';
  } else if (/\b(agendar|agenda|reservar|cita|turno|quiero\s+lavar|separar)\b/.test(m)) {
    intent = 'book_appointment';
  } else if (/\b(asesor|persona|humano|operador|agente|hablar\s+con)\b/.test(m)) {
    intent = 'human_help';
  } else if (entities.plate) {
    // Una placa suelta casi siempre es una consulta de estado.
    intent = 'check_status';
  }

  return { intent, entities };
}

let intent = 'unknown';
let entities = {};
let degradado = false;

try {
  // onError deja el error del nodo HTTP aca en vez de cortar el flujo.
  if (resp.error) {
    throw new Error('Claude no respondio: ' + JSON.stringify(resp.error).slice(0, 300));
  }

  // Un rechazo por seguridad devuelve 200 pero sin contenido util.
  if (resp.stop_reason === 'refusal') {
    throw new Error('Claude rechazo la solicitud');
  }

  // Con thinking activo content[] trae otros tipos de bloque: buscar el texto
  // en vez de asumir content[0].
  const textBlock = (resp.content || []).find((b) => b.type === 'text');
  if (!textBlock) {
    throw new Error('Respuesta sin bloque de texto');
  }

  // output_config.format garantiza JSON valido: no hace falta limpiar markdown.
  const parsed = JSON.parse(textBlock.text);
  intent = parsed.intent || 'unknown';
  entities = parsed.entities || {};
} catch (e) {
  // Degradar a palabras clave en vez de rendirse: un problema de facturacion
  // o una caida de la API no deberian dejar el bot sin entender nada.
  degradado = true;
  const porPalabras = clasificarPorPalabras(prev.originalMessage);
  intent = porPalabras.intent;
  entities = porPalabras.entities;
  console.log(
    '[intent] Claude no disponible (' + e.message + '); ' +
    'clasificado por palabras clave como: ' + intent
  );
}

if (!VALID_INTENTS.includes(intent)) {
  intent = 'unknown';
}

// Normalizar placa: sin guiones ni espacios, en mayusculas.
if (entities.plate) {
  entities.plate = String(entities.plate).replace(/[^A-Z0-9]/gi, '').toUpperCase();
} else {
  entities.plate = null;
}

return {
  intent,
  entities,
  // Queda registrado en la auditoria para poder detectar que la IA lleva
  // rato caida sin depender de que alguien mire los logs de n8n.
  degradado,
  clientPhone: prev.clientPhone,
  clientLid: prev.clientLid,
  tenantPhone: prev.tenantPhone,
  pushName: prev.pushName,
  messageId: prev.messageId,
  originalMessage: prev.originalMessage,
};

const name = $json.pushName ? ', ' + $json.pushName : '';
return {
  reply: '¡Hola' + name + '! 👋 Bienvenido al lavadero.

¿En qué te puedo ayudar hoy?

1️⃣ Estado de mi vehículo
2️⃣ Ver servicios y precios
3️⃣ Mi historial de visitas
4️⃣ Agendar un turno
5️⃣ Hablar con un asesor

Escríbeme lo que necesitas. 🚗'
};

return {
  reply: '🔍 Para consultar el estado, necesito la *placa del vehículo*.

Ejémplo: *ABC123*

¿Cuál es la placa?'
};

const data = $input.item.json;
// El nodo HTTP dejo pasar el error en vez de cortar el flujo.
if (data.error) {
  return { reply: 'No pude consultar esa información en este momento 😕\n\n¿Lo intentas de nuevo en un ratito?' };
}

const plate = $('Parsear Intencion').item.json.entities.plate;

if (!data.found) {
  return { reply: 'No encontré un turno activo para la placa *' + plate + '*.\n\n¿Quieres agendar uno? Escríbeme y te ayudo. 😊' };
}

const a = data.appointment;

// Estados reales del esquema: pending, in_progress, done, delivered, cancelled.
// Solo llegan aca los tres primeros.
const statusMap = {
  pending: '⏳ En espera',
  in_progress: '🚿 En lavado',
  done: '✅ Listo para recoger',
};
const statusText = statusMap[a.status] || a.status;

const vehiculo = [a.brand, a.model].filter(Boolean).join(' ');

// scheduled_time es TIME ('14:30:00') y puede venir null.
let cuando = new Date(a.scheduled_date).toLocaleDateString('es-CO', { day: '2-digit', month: 'short' });
if (a.scheduled_time) {
  cuando += ' a las ' + String(a.scheduled_time).slice(0, 5);
}

return {
  reply: '🚗 *Estado de tu vehículo*\n\n' +
    'Placa: *' + a.plate + '*\n' +
    (vehiculo ? 'Vehículo: ' + vehiculo + '\n' : '') +
    'Servicio: ' + a.service_name + '\n' +
    'Estado: ' + statusText + '\n' +
    'Fecha: ' + cuando +
    (a.staff_name ? '\nResponsable: ' + a.staff_name : '') +
    '\n\n¿Necesitas algo más? 😊'
};

const data = $input.item.json;

// El nodo HTTP dejo pasar el error en vez de cortar el flujo.
if (data.error) {
  return { reply: 'No pude consultar esa información en este momento 😕\n\n¿Lo intentas de nuevo en un ratito?' };
}

if (!data.services || data.services.length === 0) {
  return { reply: 'Todavía no tenemos servicios cargados. Escríbenos y te contamos. 😊' };
}

// Los precios se guardan en centavos y varian por tipo de vehiculo.
// Como no sabemos que vehiculo tiene el cliente, se muestra el mas bajo.
const cop = (centavos) => '$' + Math.round(centavos / 100).toLocaleString('es-CO');

const list = data.services.map((s) => {
  const precios = [s.price_sedan, s.price_suv, s.price_camioneta, s.price_moto, s.price_pickup]
    .map(Number)
    .filter((p) => p > 0);
  const desde = precios.length ? 'desde ' + cop(Math.min(...precios)) : 'Consultar';
  const dur = s.estimated_minutes ? ' (~' + s.estimated_minutes + ' min)' : '';
  const desc = s.description ? '\n  ' + s.description : '';
  return '• *' + s.name + '*' + dur + '\n  💰 ' + desde + desc;
}).join('\n\n');

return { reply: '🚿 *Nuestros servicios:*\n\n' + list + '\n\nEl precio final depende del tipo de vehículo.\n\n¿Agendamos alguno? 😊' };

return {
  reply: '📱 No pude identificar tu número automáticamente.\n\nPara consultar tu historial, escríbeme la *placa* de tu vehículo y te ayudo por ahí. 🚗'
};

const data = $input.item.json;

// El nodo HTTP dejo pasar el error en vez de cortar el flujo.
if (data.error) {
  return { reply: 'No pude consultar esa información en este momento 😕\n\n¿Lo intentas de nuevo en un ratito?' };
}

if (!data.found) {
  return { reply: 'No encontré visitas anteriores con tu número. ¿Es tu primera vez? ¡Bienvenido! 🎉\n\n¿Agendamos tu primer turno?' };
}

const { customer, history } = data;

if (!history || history.length === 0) {
  return { reply: 'Hola *' + customer.name + '*! Aún no tienes visitas registradas. ¿Agendamos tu primer turno? 🚗' };
}

// appointments.price esta en centavos.
const cop = (centavos) => '$' + Math.round(Number(centavos) / 100).toLocaleString('es-CO');

const list = history.map((h) => {
  const fecha = new Date(h.scheduled_date).toLocaleDateString('es-CO', { day: '2-digit', month: 'short', year: '2-digit' });
  const precio = Number(h.price) > 0 ? ' — ' + cop(h.price) : '';
  return '• ' + fecha + ': *' + h.plate + '* — ' + h.service_name + precio;
}).join('\n');

return {
  reply: '📋 *Historial de ' + customer.name + '*\n' +
    'Visitas totales: ' + customer.visit_count + '\n\n' +
    'Últimas visitas:\n' + list + '\n\n¿Agendamos una nueva? 😊'
};

return {
  reply: '🙋 *Solicitud de asesor*

Hemos recibido tu solicitud. Un asesor se comunicará contigo muy pronto.

Horario de atención: Lunes a Sábado 8am – 6pm

Gracias por tu paciencia. 🙏'
};

return {
  reply: '😊 No entendí bien tu mensaje. Puedo ayudarte con:

1️⃣ Estado de tu vehículo
2️⃣ Ver precios y servicios
3️⃣ Tu historial de visitas
4️⃣ Agendar un turno
5️⃣ Hablar con un asesor

¿Con cuál te ayudo?'
};

// Arma las entradas de auditoria para POST /log. Corre DESPUES de responder al
// webhook: el cliente ya recibio su mensaje, asi que registrar no le suma latencia.

// El Webhook es el unico nodo que corre en todas las ramas. 'Parsear Intencion'
// se saltea cuando el cliente esta a mitad de un agendamiento, y referenciar un
// nodo que no se ejecuto tira error, por eso va dentro de un try.
const body = $('Webhook').item.json.body || {};
const reply = $input.item.json.reply || '';

let flowStep = 'booking';
try {
  const p = $('Parsear Intencion').item.json;
  // El prefijo permite ver desde la BD cuando la IA estuvo caida.
  flowStep = (p.degradado ? 'kw:' : '') + (p.intent || 'unknown');
} catch (e) {
  // Rama de agendamiento en curso: no hubo clasificacion de intencion.
}

// Se registra con lo que haya: el LID es identidad valida por si solo.
if (!body.phone && !body.waLid) {
  console.log('[auditoria] omitida: mensaje sin identidad', body.messageId);
  return [];
}

const base = {
  phone: body.phone || null,
  // waLid iba faltando en el cuerpo que se enviaba al backend: como WhatsApp
  // casi nunca entrega el telefono, /log respondia 400 y la auditoria no
  // registraba nada. El onError lo ocultaba y el reintento lo duplicaba.
  waLid: body.waLid || null,
  flowStep,
  messageId: body.messageId,
};

const mensajes = [];
if (body.message) mensajes.push({ ...base, direction: 'inbound', content: body.message });
if (reply) mensajes.push({ ...base, direction: 'outbound', content: reply });

if (mensajes.length === 0) return [];

// Un solo item con todas las entradas: antes salia un item por entrada y el
// nodo HTTP se ejecutaba una vez por cada uno, gastando cuota de mas.
return [{ json: { tenantPhone: body.tenantPhone, mensajes } }];

const data = $input.item.json;
const ctx = $('Parsear Intencion').item.json;

// Sin ninguna identidad no se puede guardar la sesion del cliente.
if (!ctx.clientLid && !ctx.clientPhone) {
  return { reply: '📅 Para agendarte necesito identificarte.\n\nEscríbeme la *placa* de tu vehículo y seguimos por ahí. 🚗' };
}

if (!data.reply) {
  // Dejar el motivo en el log: al cliente no se le puede mostrar, pero sin
  // esto hay que adivinar por que fallo el agendamiento.
  console.log('[agendamiento] el backend no devolvio reply:', JSON.stringify(data).slice(0, 400));
  return { reply: 'No pude iniciar el agendamiento en este momento. ¿Lo intentamos de nuevo? 🙏' };
}

return { reply: data.reply };
